"""PAC website speed-up: installs speedup.py and hooks it into app.py. Backup: app.py.bak-speedup. Safe to run twice."""
import base64, os, shutil, sys
ROOT = sys.argv[1] if len(sys.argv) > 1 else "."
MOD = base64.b64decode("").decode()
open(os.path.join(ROOT, "speedup.py"), "w", encoding="utf-8").write(MOD)
p = os.path.join(ROOT, "app.py"); s = open(p, encoding="utf-8").read()
hook = "import speedup  # noqa: E402  (short cache for start-up data, browser caching)\nspeedup.init(app)\n"
anchor = "app.before_request(auth.gatekeeper)\n"
if hook in s:
    print("SPEEDUP ALREADY INSTALLED (speedup.py refreshed)")
elif s.count(anchor) != 1:
    print("PROBLEM: could not find the place to hook in. Nothing changed in app.py.")
else:
    if not os.path.exists(p + ".bak-speedup"): shutil.copyfile(p, p + ".bak-speedup")
    open(p, "w", encoding="utf-8").write(s.replace(anchor, anchor + hook))
    print("SPEEDUP INSTALLED")
